        return ResponseEntity.status(response.getCode() == 200 ? 200 : response.getCode()).body(response);
    }

    @PostMapping("/{orderId}/sites")
    public ResponseEntity<ApiResponse<Object>> addSite(@PathVariable Long orderId,
